import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &a[i])
	}

	originalOnes := 0
	for _, v := range a {
		if v == 1 {
			originalOnes++
		}
	}

	// Create the gain array: 1 for 0s, -1 for 1s
	gain := make([]int, n)
	for i := 0; i < n; i++ {
		if a[i] == 0 {
			gain[i] = 1
		} else {
			gain[i] = -1
		}
	}

	// Kadane's algorithm to find maximum subarray sum
	maxCurrent := gain[0]
	maxGlobal := gain[0]
	for i := 1; i < n; i++ {
		if gain[i] > maxCurrent+gain[i] {
			maxCurrent = gain[i]
		} else {
			maxCurrent += gain[i]
		}
		if maxCurrent > maxGlobal {
			maxGlobal = maxCurrent
		}
	}

	fmt.Println(originalOnes + maxGlobal)
}
